public class Solution
{
    public int CountBooleanParenthesizations(string expression, bool desired)
    {
        if (expression.Length == 0)
            return 0;
        int count = (expression.Length + 1) / 2;
        int[,] truth = new int[count, count], falsity = new int[count, count];
        for (int i = 0; i < count; ++i)
        {
            truth[i, i] = expression[2 * i] == '1' ? 1 : 0;
            falsity[i, i] = 1 - truth[i, i];
        }
        for (int length = 2; length <= count; ++length)
        {
            for (int low = 0; low + length <= count; ++low)
            {
                int high = low + length - 1;
                for (int split = low; split < high; ++split)
                {
                    int lt = truth[low, split], lf = falsity[low, split],
